import { ref, computed } from 'vue'

export interface User {
  id: string
  username: string
  email: string
}

const currentUser = ref<User | null>(null)
const isLoggedIn = computed(() => currentUser.value !== null)

const getUsers = (): Record<string, { password: string; user: User }> => {
  const stored = localStorage.getItem('users')
  return stored ? JSON.parse(stored) : {}
}

const saveUsers = (users: Record<string, { password: string; user: User }>) => {
  localStorage.setItem('users', JSON.stringify(users))
}

export function useAuth() {
  const register = (username: string, email: string, password: string): boolean => {
    const users = getUsers()
    if (users[email]) {
      return false
    }
    const user: User = {
      id: Date.now().toString(),
      username,
      email,
    }
    users[email] = { password, user }
    saveUsers(users)
    return true
  }

  const login = (email: string, password: string): boolean => {
    const users = getUsers()
    const stored = users[email]
    if (stored && stored.password === password) {
      currentUser.value = stored.user
      localStorage.setItem('user', JSON.stringify(stored.user))
      return true
    }
    return false
  }

  const logout = () => {
    currentUser.value = null
    localStorage.removeItem('user')
  }

  const checkAuth = () => {
    const storedUser = localStorage.getItem('user')
    if (storedUser) {
      currentUser.value = JSON.parse(storedUser)
    }
  }

  return {
    currentUser,
    isLoggedIn,
    register,
    login,
    logout,
    checkAuth,
  }
}